"""Deterministic, lossless output layout for opcodes_gen.py.

The generator continues to produce exactly its old Python and Cython source in
memory. This final emission stage partitions it into bounded source components.
No instruction, dispatcher comparison, declaration, decorator or byte is edited.
"""
from __future__ import annotations

import argparse
import ast
import hashlib
import importlib.util
import os
import re
import tempfile
from pathlib import Path

DEFAULT_MAX_LINES = 900
FACADE = b'''# Generated by opcodes_gen.py; do not edit.
# The runtime and native compiler reconstruct the same original source bytes.
from ._opcodes_runtime import load_into as _load_opcode_components
_load_opcode_components(globals())
del _load_opcode_components
'''


def _runtime():
    path = Path(__file__).with_name("_opcodes_runtime.py")
    spec = importlib.util.spec_from_file_location("_opcode_layout_runtime", path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def _source_blocks(source):
    text = source.decode("utf-8")
    lines = text.splitlines(keepends=True)
    tree = ast.parse(text)
    previous = 0
    for index, node in enumerate(tree.body):
        # Comments and blank lines remain attached to the preceding block.
        end = tree.body[index + 1].lineno - 1 if index + 1 < len(tree.body) else len(lines)
        if isinstance(node, ast.FunctionDef):
            if node.name == "execute_opcode":
                kind = "dispatch"
            elif re.fullmatch(r"[A-Z]+_[0-9A-F]{2,3}", node.name):
                kind = "instructions"
            else:
                kind = "shared"
        elif isinstance(node, ast.Assign) and any(
            isinstance(target, ast.Name) and target.id in {"CPU_COMMANDS", "OPCODE_LENGTHS"}
            for target in node.targets
        ):
            kind = "tables"
        else:
            kind = "shared"
        yield kind, lines[previous:end]
        previous = end
    if not tree.body:
        raise ValueError("opcode source is empty")


def _declaration_blocks(declarations):
    # Include boundaries must never separate a Cython decorator from its cdef.
    lines = declarations.decode("utf-8").splitlines(keepends=True)
    pending = []
    for line in lines:
        pending.append(line)
        if line.lstrip().startswith("@"):
            continue
        if line.startswith("cdef ") and "(" in line:
            yield "signatures", pending
            pending = []
    if pending:
        yield "signatures", pending


def _partition(blocks, limit, split_large):
    parts, current, current_kind = [], [], None
    for kind, block in blocks:
        if current and (kind != current_kind or len(current) + len(block) > limit):
            parts.append((current_kind, current))
            current = []
        if len(block) > limit:
            if not split_large:
                raise ValueError("a Cython declaration block exceeds the line bound")
            # A generated dispatcher spans components but is never re-authored.
            # Components are concatenated before parsing, not standalone modules.
            for start in range(0, len(block), limit):
                parts.append((kind, block[start:start + limit]))
            current_kind = None
        else:
            current_kind = kind
            current.extend(block)
    if current:
        parts.append((current_kind, current))
    return parts


def render_layout(source, declarations, max_lines=DEFAULT_MAX_LINES):
    """Return path->bytes for an entirely deterministic, byte-reversible layout."""
    if type(max_lines) is not int or not 1 <= max_lines < 1000:
        raise ValueError("max_lines must be an integer from 1 through 999")
    source = source.encode("utf-8") if isinstance(source, str) else source
    declarations = declarations.encode("utf-8") if isinstance(declarations, str) else declarations
    if not source or not declarations:
        raise ValueError("both legacy source files are required")
    result, groups = {}, []
    for prefix, original, blocks, split_large in (
        ("source", source, _source_blocks(source), True),
        ("declarations", declarations, _declaration_blocks(declarations), False),
    ):
        entries = []
        for index, (kind, lines) in enumerate(_partition(blocks, max_lines, split_large)):
            data = "".join(lines).encode("utf-8")
            digest = hashlib.sha256(data).hexdigest()
            name = f"opcode_components/{prefix}_{kind}_{index:03d}_{digest[:12]}.pxi"
            result[name] = data
            entries.append((name, digest))
        if b"".join(result[name] for name, _ in entries) != original:
            raise ValueError("layout emission changed source bytes")
        groups.append(tuple(entries))
    values = {
        "FORMAT_VERSION": 1,
        "MAX_LINES": max_lines,
        "SOURCE_SHA256": hashlib.sha256(source).hexdigest(),
        "DECLARATIONS_SHA256": hashlib.sha256(declarations).hexdigest(),
        "SOURCE_PARTS": groups[0],
        "DECLARATION_PARTS": groups[1],
    }
    manifest = "# Generated by opcodes_gen.py; literal data only.\n"
    for key, value in values.items():
        if key.endswith("_PARTS"):
            manifest += key + " = (\n" + "".join("    " + repr(entry) + ",\n" for entry in value) + ")\n"
        else:
            manifest += key + " = " + repr(value) + "\n"
    result["_opcodes_manifest.py"] = manifest.encode("utf-8")
    result["opcodes.py"] = FACADE
    result["opcodes.pxd"] = _runtime().declaration_facade(groups[1])
    if any(len(data.decode("utf-8").splitlines()) >= 1000 for data in result.values()):
        raise ValueError("generated output exceeds the repository line bound")
    return result


def _write(path, data):
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.exists() and path.read_bytes() == data:
        return
    fd, temp = tempfile.mkstemp(prefix=".opcode-write-", dir=path.parent)
    try:
        with os.fdopen(fd, "wb") as stream:
            stream.write(data)
        os.replace(temp, path)
    finally:
        if os.path.exists(temp):
            os.unlink(temp)


def emit_layout(source, declarations, output_dir, max_lines=DEFAULT_MAX_LINES):
    """Publish components first and their manifest last. Never delete user files."""
    output_dir = Path(output_dir)
    runtime = _runtime()
    previous = set()
    if (output_dir / runtime.MANIFEST_NAME).exists():
        runtime.read_sources(output_dir)  # Do not overwrite a damaged/edited layout.
        old = runtime._manifest(output_dir)
        previous = {name for key in ("SOURCE_PARTS", "DECLARATION_PARTS") for name, _ in old[key]}
    result = render_layout(source, declarations, max_lines)
    for name in result:
        path = output_dir / name
        if path.is_symlink() or path.parent.is_symlink():
            raise ValueError("refusing to write through a symbolic link: " + name)
        if name.startswith("opcode_components/") and path.exists() and name not in previous:
            if path.read_bytes() != result[name]:
                raise ValueError("refusing to overwrite an unowned component: " + name)
    for name, data in result.items():
        if name != runtime.MANIFEST_NAME:
            _write(output_dir / name, data)
    _write(output_dir / runtime.MANIFEST_NAME, result[runtime.MANIFEST_NAME])
    if runtime.read_sources(output_dir) != (bytes(source, "utf-8") if isinstance(source, str) else source,
                                             bytes(declarations, "utf-8") if isinstance(declarations, str) else declarations):
        raise ValueError("published layout failed its byte parity check")
    for name in sorted(previous - set(result)):
        (output_dir / name).unlink()
    return result


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--legacy-python", type=Path, required=True)
    parser.add_argument("--legacy-pxd", type=Path, required=True)
    parser.add_argument("--output-dir", type=Path, required=True)
    parser.add_argument("--max-lines", type=int, default=DEFAULT_MAX_LINES)
    args = parser.parse_args(argv)
    result = emit_layout(args.legacy_python.read_bytes(), args.legacy_pxd.read_bytes(),
                         args.output_dir, args.max_lines)
    print(f"Emitted {len(result)} files; legacy Python and Cython bytes unchanged.")


if __name__ == "__main__":
    main()
